,"type":"text","nullable":false,"immutable":true,"queryable":true},{"column":"expires_at","bodyField":"expiresAt","type":"text","nullable":false,"queryable":true},{"column":"status","bodyField":"status","type":"text","nullable":false,"state":true,"queryable":true},{"column":"owner_identity_id","bodyField":"ownerIdentityId","type":"text","nullable":true,"queryable":true},{"column":"due_date","bodyField":"dueDate","type":"text","nullable":true,"queryable":true},{"column":"priority","bodyField":"priority","type":"text","nullable":true,"queryable":true},{"column":"reason","bodyField":"reason","type":"text","nullable":true},{"column":"execution_id","bodyField":"executionId","type":"text","nullable":true}],"stateField":"status","permittedTransitions":{"pending":["sent","cancelled"],"sent":[],"cancelled":[]},"terminalImmutableFields":{},"immutableFields":["id","contractId","milestone","expiresAt","createdAt"],"unique":[{"name":"contract_reminders_contract_milestone_unique","fields":["contractId","expiresAt","milestone"]}],"foreignKeys":[{"column":"contract_id","target":"employment_contracts","nullable":false,"deferred":false,"external":false},{"column":"execution_id","target":"action_executions","nullable":true,"deferred":false,"external":false,"requiredContractVersion":2},{"column":"owner_identity_id","target":"directory_identities","nullable":true,"deferred":false,"external":false}],"compositeForeignKeys":[],"normalizedChildren":[],"queryFields":["contractId","milestone","expiresAt","status","ownerIdentityId","dueDate","priority"],"ownerField":"ownerIdentityId","dateField":"expiresAt","bodyGuards":[{"field":"dueDate","kind":"business_date"},{"field":"priority","kind":"priority"},{"field":"reason","kind":"reason"}],"requiredWriteFields":["ownerIdentityId","dueDate","priority","reason","executionId"],"insertStates":["pending"],"appendOnly":false,"bodyFields":["id","rowVersion","contractId","milestone","expiresAt","status","ownerIdentityId","dueDate","priority","reason","ex