etColumns":["id","version"],"deferred":true}],"normalizedChildren":[],"queryFields":["employeeId","policyDocumentId","policyVersion","status","dueDate","ownerIdentityId","priority"],"ownerField":"ownerIdentityId","dateField":"dueDate","bodyGuards":[{"field":"dueDate","kind":"business_date"},{"field":"priority","kind":"priority"},{"field":"reason","kind":"reason"}],"requiredWriteFields":["ownerIdentityId","dueDate","priority","reason","executionId"],"insertStates":["pending"],"appendOnly":false,"bodyFields":["id","rowVersion","employeeId","policyDocumentId","policyVersion","status","dueDate","ownerIdentityId","priority","reason","executionId","createdAt","acknowledgedAt"]},{"table":"badge_effect_events","storage":"new","bodyColumn":"body","markerlessV2Discriminators":[],"projectionEqualities":[],"columns":[{"column":"badge_id","bodyField":"badgeId","type":"text","nullable":false,"immutable":true,"queryable":true},{"column":"employee_id","bodyField":"employeeId","type":"text","nullable":false,"immutable":true,"queryable":true},{"column":"actor_id","bodyField":"actorId","type":"text","nullable":false,"immutable":true,"queryable":true},{"column":"execution_id","bodyField":"executionId","type":"text","nullable":false,"immutable":true,"queryable":true},{"column":"effect","bodyField":"effect","type":"text","nullable":false,"immutable":true,"queryable":true},{"column":"created_at","bodyField":"createdAt","type":"text","nullable":false,"immutable":true,"queryable":true}],"permittedTransitions":{},"terminalImmutableFields":{},"immutableFields":["id","badgeId","employeeId","actorId","executionId","effect","createdAt"],"unique":[{"name":"badge_effect_events_execution_unique","fields":["executionId"]}],"foreignKeys":[{"column":"badge_id","target":"mock_badges","nullable":false,"deferred":false,"external":false},{"column":"employee_id","target":"employees","nullable":false,"deferred":false,"external":false},{"column":"actor_id","target":"profiles","nullable":false,"deferred":false,"external":false},{"column":"execution_id","target":"action_executions","nullable":false,"deferred":false,"external":false,"requiredContractVersion":2}],"compositeForeignKeys":[],"normalizedChildren":[],"queryFields":["badgeId","employeeId","actorId","executionId","effect","createdAt"],"bodyGuards":[{"field":"reason","kind":"reason"}],"appendOnly":true,"bodyFields":["id","rowVersion","badgeId","employeeId","actorId","executionId","effect","createdAt","reason"]}]$completeness_manifest$::jsonb);

create temporary table workflow_completeness_state(
  revision bigint not null, installed boolean not null, digest text not null
) on commit drop;
create temporary table workflow_completeness_rows(
  table_name text not null,id text not null,body_text text not null,
  row_version bigint,contract_marker integer,original_columns jsonb not null,
  primary key(table_name,id)
) on commit drop;
create temporary table workflow_completeness_trigger_modes(
  table_oid oid not null,trigger_name text not null,enabled "char" not null,
  primary key(table_oid,trigger_name)
) on commit drop;

do $acquire$
declare item record; actual bigint; step_digest text; installed_digest text;
begin
  if (select count(*) from nexus_private.workflow_manifest)<>62
    or exists(select 1 from pg_temp.workflow_completeness_manifest n
      full join nexus_private.workflow_manifest o using(table_name)
      where n.table_name is null or o.table_name is null) then
    raise exception 'Workflow completeness requires the exact preceding manifest' using errcode='23514';
  end if;
  -- Ownership is checked using the real migration caller, outside any definer.
  -- The adapter flag is never an authority to bypass row or projection guards.
  for item in
    select c.oid,c.relowner,n.nspname,c.relname
    from pg_catalog.pg_class c join pg_catalog.pg_namespace n on n.oid=c.relnamespace
    where n.nspname='public' and (c.relname='appmeta'
      or c.relname in(select table_name from nexus_private.workflow_manifest)
      or c.relname in(select child->>'table' from nexus_private.workflow_manifest m
        cross join lateral jsonb_array_elements(m.definition->'normalizedChildren') child))
    order by case when c.relname='appmeta' then 0 else 1 end,c.relname
  loop
    if not pg_catalog.pg_has_role(current_user,item.relowner,'USAGE')
      and not (select rolsuper from pg_catalog.pg_roles where rolname=current_user) then
      raise exception 'Workflow completeness requires table ownership' using errcode='42501';
    end if;
    execute format('lock table %I.%I in access exclusive mode',item.nspname,item.relname);
  end loop;
  select revision into strict actual from public.appmeta where singleton=1 for update;
  if (select workflow_adapter_write from public.appmeta where singleton=1)<>0 then
    raise exception 'Workflow completeness found an active adapter write' using errcode='23514';
  end if;
  if exists(select 1 from nexus_private.workflow_manifest m
    cross join (values('workflow_guard'),('nexus_revision')) required(trigger_name)
    left join pg_catalog.pg_trigger installed on installed.tgrelid=format('public.%I',m.table_name)::regclass
      and installed.tgname=required.trigger_name
    where installed.oid is null or installed.tgenabled not in('O','A')) then
    raise exception 'Workflow completeness requires active preceding guards' using errcode='23514';
  end if;
  create table if not exists nexus_private.workflow_projection_migrations(
    id text primary key,definition_digest text not null
  );
  revoke all on nexus_private.workflow_projection_migrations from public,anon,authenticated,service_role;
  select md5(string_agg(table_name||definition::text,E'\n' order by table_name))
    into step_digest from pg_temp.workflow_completeness_manifest;
  select definition_digest into installed_digest from nexus_private.workflow_projection_migrations
    where id='202610030002_workflow_projection_completeness';
  if installed_digest is null
    and pg_catalog.to_regclass('public.workflow_offboarding_plan_assignments') is not null then
    raise exception 'Workflow completeness found a preexisting assignment projection' using errcode='23514';
  end if;
  if installed_digest is not null and installed_digest<>step_digest then
    raise exception 'Workflow completeness manifest changed without a new schema version' using errcode='23514';
  end if;
  if installed_digest is not null and exists(select 1 from pg_temp.workflow_completeness_manifest n
    join nexus_private.workflow_manifest o using(table_name) where n.definition is distinct from o.definition) then
    raise exception 'Workflow completeness stored manifest does not match its ledger' using errcode='23514';
  end if;
  insert into pg_temp.workflow_completeness_state values(actual,installed_digest is not null,step_digest);
  for item in select table_name,definition from nexus_private.workflow_manifest order by table_name loop
    execute format('insert into pg_temp.workflow_completeness_rows select %L,id,%I::text,row_version,%s,to_jsonb(t) from public.%I t',
      item.table_name,item.definition->>'bodyColumn',
      case when item.definition->>'storage'='mixed' then 'workflow_contract_version' else 'null::integer' end,item.table_name);
  end loop;
  if installed_digest is null then
    -- Extension JSON never constituted reviewed incident state. Do not adopt it.
    if exists(select 1 from public.incidents where payload->>'escalationStage' is not null
      or payload->>'escalationLifecycleId' is not null or payload->>'escalationEventId' is not null) then
      raise exception 'Workflow completeness contains unprotected legacy incident proof' using errcode='23514';
    end if;
    -- Unknown trigger side effects cannot be proved historical-data preserving.
    if exists(select 1 from pg_catalog.pg_trigger t join pg_catalog.pg_class c on c.oid=t.tgrelid
      join pg_catalog.pg_namespace n on n.oid=c.relnamespace
      where n.nspname='public' and not t.tgisinternal and t.tgenabled<>'D'
        and c.relname in(select table_name from nexus_private.workflow_manifest)
        and t.tgname not in('workflow_guard','workflow_children','nexus_revision')) then
      raise exception 'Workflow completeness cannot suspend an unknown application trigger' using errcode='23514';
    end if;
    insert into pg_temp.workflow_completeness_trigger_modes
      select t.tgrelid,t.tgname,t.tgenabled from pg_catalog.pg_trigger t
      join pg_catalog.pg_class c on c.oid=t.tgrelid join pg_catalog.pg_namespace n on n.oid=c.relnamespace
      where n.nspname='public' and not t.tgisinternal
        and t.tgname in('workflow_guard','workflow_children','nexus_revision')
        and c.relname in(select table_name from nexus_private.workflow_manifest);
    for item in select * from pg_temp.workflow_completeness_trigger_modes loop
      execute format('alter table %s disable trigger %I',item.table_oid::regclass,item.trigger_name);
    end loop;
  end if;
end $acquire$;

-- The PostgreSQL ledger is private and uses canonical JSONB metadata MD5 only as
-- an equality fingerprint. It neither replaces Supabase's migration ledger nor
-- rewrites the immutable SQLite historical SHA256 descriptors.
do $schema$
declare d jsonb; c jsonb; f jsonb; u jsonb; tbl text; sql_type text; colname text;
  field text; unique_columns text; unique_states text; unique_predicate text; previous_unique jsonb;
  prior_columns text[]; assignments text; clause text; expected_keys smallint[];
  expected_key smallint; native_keys int2vector; key_position integer;
begin
  if (select installed from pg_temp.workflow_completeness_state) then return; end if;
  for d in select definition from pg_temp.workflow_completeness_manifest order by table_name loop
    tbl:=d->>'table'; assignments:='';
    select array_agg(attname::text) into prior_columns from pg_catalog.pg_attribute
      where attrelid=format('public.%I',tbl)::regclass and attnum>0 and not attisdropped;
    for c in select value from jsonb_array_elements(d->'columns') loop
      sql_type:=case c->>'type' when 'integer' then 'bigint' when 'real' then 'double precision'
        when 'boolean' then 'boolean' when 'json' then 'jsonb' else 'text' end;
      execute format('alter table public.%I add column if not exists %I %s',tbl,c->>'column',sql_type);
      if not (c->>'column'=any(prior_columns)) and not coalesce((c->>'legacyOnly')::boolean,false)
        and not (tbl='incidents' and c->>'bodyField' like 'escalation%') then
        if tbl='mock_tickets' and c->>'column'='employee_assignee_id' then
          clause:='case when assignee_id is null and exists(select 1 from public.employees e where e.id=payload->>''assigneeId'') then payload->>''assigneeId'' else null end';
        elsif c->>'type'='json' then
          clause:=format('%I #> %L::text[]',d->>'bodyColumn',string_to_array(c->>'bodyField','.'));
        else clause:=format('(%I #>> %L::text[])::%s',d->>'bodyColumn',string_to_array(c->>'bodyField','.'),sql_type); end if;
        assignments:=assignments||case when assignments='' then '' else ',' end||format('%I=%s',c->>'column',clause);
      end if;
    end loop;
    if assignments<>'' then execute format('update public.%I set %s',tbl,assignments); end if;
    if d ? 'legacyQuarantineColumn' then
      execute format('alter table public.%I add column if not exists %I integer not null default 0 check(%I in(0,1))',
        tbl,d->>'legacyQuarantineColumn',d->>'legacyQuarantineColumn');
      -- Preserve the historical profile FK/projection bytes forever.
      execute format('update public.%I set %I=case when assignee_id is not null or employee_assignee_id is null then 1 else 0 end',tbl,d->>'legacyQuarantineColumn');
    end if;
  end loop;
  -- Reconcile only reviewed unique definitions that differ from the preceding
  -- manifest, before replacing that manifest. This includes branch open state,
  -- terminal onboarding returns, and contract expiry identity. IF NOT EXISTS
  -- alone would silently retain stale keys/predicates. Twin of the canonical
  -- unique-index builder in 202610020002_workflow_v2; no domain row is rewritten.
  for d in select definition from pg_temp.workflow_completeness_manifest order by table_name loop
    tbl:=d->>'table';
    for u in select entries.constraint_definition from jsonb_array_elements(d->'unique') entries(constraint_definition) loop
      select old_entries.constraint_definition into previous_unique
        from nexus_private.workflow_manifest preceding
        cross join lateral jsonb_array_elements(preceding.definition->'unique') old_entries(constraint_definition)
        where preceding.table_name=tbl and old_entries.constraint_definition->>'name'=u->>'name';
      if previous_unique is not distinct from u then continue; end if;
      unique_columns:=''; expected_keys:='{}'::smallint[];
      for field in select jsonb_array_elements_text(u->'fields') loop
        if field='id' then colname:='id'; elsif field='rowVersion' then colname:='row_version';
        else select projected.column_definition->>'column' into strict colname
          from jsonb_array_elements(d->'columns') projected(column_definition)
          where projected.column_definition->>'bodyField'=field; end if;
        select native_column.attnum into strict expected_key from pg_catalog.pg_attribute native_column
          where native_column.attrelid=format('public.%I',tbl)::regclass
            and native_column.attname=colname and native_column.attnum>0 and not native_column.attisdropped;
        expected_keys:=array_append(expected_keys,expected_key);
        unique_columns:=unique_columns||case when unique_columns='' then '' else ',' end||format('%I',colname);
      end loop;
      if unique_columns='' then raise exception 'Workflow completeness unique fields are empty' using errcode='23514'; end if;
      unique_predicate:=case when d->>'storage'='mixed' then 'workflow_contract_version=2' else 'true' end;
      if coalesce((u->>'openOnly')::boolean,false) then
        select string_agg(quote_literal(open_states.state_name),',' order by open_states.position) into unique_states
          from jsonb_array_elements_text(u->'openStates') with ordinality open_states(state_name,position);
        if unique_states is null then raise exception 'Workflow completeness open states are empty' using errcode='23514'; end if;
        unique_predicate:=unique_predicate||format(' and nexus_private.workflow_state(%I,%L::jsonb) in (%s)',d->>'bodyColumn',d::text,unique_states);
      end if;
      execute format('drop index if exists public.%I',u->>'name');
      if unique_predicate='true' then
        execute format('create unique index %I on public.%I(%s)',u->>'name',tbl,unique_columns);
      else execute format('create unique index %I on public.%I(%s) where %s',u->>'name',tbl,unique_columns,unique_predicate); end if;
      -- Construction rejects duplicates atomically. Also verify exact ordered
      -- native keys, uniqueness, validity/readiness, and expected partialness.
      select native_index.indkey into native_keys from pg_catalog.pg_index native_index
        where native_index.indexrelid=format('public.%I',u->>'name')::regclass
          and native_index.indisunique and native_index.indisvalid and native_index.indisready
          and native_index.indnkeyatts=cardinality(expected_keys)
          and (native_index.indpred is null)=(unique_predicate='true');
      if not found then raise exception 'Workflow completeness unique index is invalid' using errcode='23514'; end if;
      key_position:=0;
      foreach expected_key in array expected_keys loop
        if native_keys[key_position] is distinct from expected_key then
          raise exception 'Workflow completeness unique key order is invalid' using errcode='23514';
        end if;
        key_position:=key_position+1;
      end loop;
    end loop;
  end loop;
  update nexus_private.workflow_manifest m set definition=n.definition
    from pg_temp.workflow_completeness_manifest n where m.table_name=n.table_name;
  create unique index if not exists workflow_incidents_escalation_pointer_unique
    on public.incidents(id,escalation_lifecycle_id,escalation_event_id);
  alter table public.incident_escalation_events add column if not exists workflow_incident_proof_id text
    generated always as (case when jsonb_typeof(body->'reason')='string'
      and jsonb_typeof(body->'evidenceIds')='array' then incident_id else null end) stored;
  if not exists(select 1 from pg_catalog.pg_constraint where conrelid='public.incident_escalation_events'::regclass
    and conname='wf_incident_escalation_current_pointer_fk') then
    alter table public.incident_escalation_events add constraint wf_incident_escalation_current_pointer_fk
      foreign key(workflow_incident_proof_id,lifecycle_id,id)
      references public.incidents(id,escalation_lifecycle_id,escalation_event_id)
      on delete no action deferrable initially deferred;
  end if;
  for d in select definition from nexus_private.workflow_manifest loop
    tbl:=d->>'table';
    for f in select value from jsonb_array_elements(d->'foreignKeys') loop
      colname:='wf_'||tbl||'_'||(f->>'column')||'_fk';
      if not exists(select 1 from pg_catalog.pg_constraint where conrelid=format('public.%I',tbl)::regclass and conname=left(colname,63)) then
        execute format('alter table public.%I add constraint %I foreign key(%I) references public.%I(id) on delete no action deferrable initially deferred',tbl,colname,f->>'column',f->>'target');
      end if;
      if f->>'requiredContractVersion'='2' then
        colname:=regexp_replace(f->>'column','_id$','')||'_contract_version';
        execute format('alter table public.%I add column if not exists %I integer generated always as (case when %s%I is not null then 2 else null end) stored',
          tbl,colname,case when d->>'storage'='mixed' then 'workflow_contract_version=2 and ' else '' end,f->>'column');
        execute format('create unique index if not exists %I on public.%I(id,workflow_contract_version)','workflow_'||(f->>'target')||'_contract_reference_unique',f->>'target');
        colname:='wf_'||tbl||'_'||(f->>'column')||'_contract_fk';
        if not exists(select 1 from pg_catalog.pg_constraint where conrelid=format('public.%I',tbl)::regclass and conname=left(colname,63)) then
          execute format('alter table public.%I add constraint %I foreign key(%I,%I) references public.%I(id,workflow_contract_version) on delete no action deferrable initially deferred',
            tbl,colname,f->>'column',regexp_replace(f->>'column','_id$','')||'_contract_version',f->>'target');
        end if;
      end if;
    end loop;
    for c in select value from jsonb_array_elements(d->'columns') where coalesce((value->>'queryable')::boolean,false)
      and not coalesce((value->>'legacyOnly')::boolean,false) loop
      execute format('create index if not exists %I on public.%I(%I,id)','wf_'||tbl||'_'||(c->>'column')||'_lookup',tbl,c->>'column');
    end loop;
  end loop;
  create table if not exists public.workflow_offboarding_plan_assignments(
    plan_id text not null references public.offboarding_plans(id) on delete no action deferrable initially deferred,
    assignment_id text not null references public.asset_assignments(id) on delete no action deferrable initially deferred,
    primary key(plan_id,assignment_id)
  );
  create unique index if not exists workflow_offboarding_plan_assignments_unique
    on public.workflow_offboarding_plan_assignments(plan_id,assignment_id);
  create index if not exists workflow_offboarding_plan_assignments_target_lookup
    on public.workflow_offboarding_plan_assignments(assignment_id,plan_id);
  -- New child only: existing policies/authentication are untouched.
  alter table public.workflow_offboarding_plan_assignments enable row level security;
  revoke all on public.workflow_offboarding_plan_assignments from public,anon,authenticated,service_role;
  grant select on public.workflow_offboarding_plan_assignments to service_role;
  insert into public.workflow_offboarding_plan_assignments(plan_id,assignment_id)
    select p.id,a.value from public.offboarding_plans p
    cross join lateral jsonb_array_elements_text(p.body->'assetAssignmentIds') a(value)
    on conflict do nothing;
  if exists(select 1 from public.workflow_offboarding_plan_assignments s
    join public.offboarding_plans p on p.id=s.plan_id
    join public.offboarding_cases c on c.id=p.case_id
    join public.asset_assignments a on a.id=s.assignment_id
    where a.employee_id is distinct from c.employee_id) then
    raise exception 'Workflow completeness contains incompatible assignment ownership' using errcode='23514';
  end if;
end $schema$;

-- SQL twins of workflow-projections.ts guardSchema and SQLite bodyGuardChecks.
-- JavaScript bounds strings by UTF16 code units; PostgreSQL length alone would
-- admit 500 astral code points (1000 units), so count them explicitly.
create or replace function nexus_private.workflow_utf16_length(value text) returns integer
language sql immutable strict set search_path='' as $$
  select coalesce(sum(case when item='' then 0 when ascii(item)>65535 then 2 else 1 end),0)::integer
    from regexp_split_to_table(value,'') chars(item)
$$;
create or replace function nexus_private.workflow_identifier(value jsonb) returns boolean
language sql immutable set search_path='' as $$
  select coalesce(jsonb_typeof(value)='string' and length(value #>> '{}') between 1 and 160
    and (value #>> '{}') ~ '^[A-Za-z0-9][A-Za-z0-9._:-]*$',false)
$$;
create or replace function nexus_private.workflow_business_date(value jsonb) returns boolean
language plpgsql immutable set search_path='' as $$
declare text_value text; parsed date;
begin
  if jsonb_typeof(value) is distinct from 'string' then return false; end if;
  text_value:=value #>> '{}';
  if text_value !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or left(text_value,4)='0000' then return false; end if;
  begin parsed:=text_value::date;
  exception when datetime_field_overflow or invalid_datetime_format then return false; end;
  return to_char(parsed,'YYYY-MM-DD')=text_value;
end $$;
create or replace function nexus_private.workflow_body_guard(value jsonb,rule jsonb,allow_legacy boolean default false) returns boolean
language plpgsql immutable set search_path='' as $$
declare text_value text; field_count integer;
begin
  if value is null or value='null'::jsonb then return true; end if;
  text_value:=value #>> '{}';
  case rule->>'kind'
    when 'nonnegative_integer' then
      if jsonb_typeof(value) is distinct from 'number' then return false; end if;
      return text_value::numeric between 0 and 9007199254740991
        and trunc(text_value::numeric)=text_value::numeric;
    when 'business_date' then return nexus_private.workflow_business_date(value);
    when 'priority' then return jsonb_typeof(value)='string' and text_value in('normal','high');
    when 'identifier' then return nexus_private.workflow_identifier(value);
    when 'reason' then return jsonb_typeof(value)='string'
      and nexus_private.workflow_utf16_length(text_value) between 1 and 500
      and length(btrim(text_value,U&'\0009\000A\000B\000C\000D \00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF'))>0;
    when 'escalation_stage' then return jsonb_typeof(value)='string' and text_value in('un_escalated','team_requested');
    when 'document_status' then return jsonb_typeof(value)='string' and (text_value in('accepted','withdrawn','replaced')
      or (allow_legacy and text_value in('missing','received','waived')));
    when 'id_array' then
      if jsonb_typeof(value)<>'array' then return false; end if;
      return jsonb_array_length(value) between coalesce((rule->>'minimum')::integer,0) and coalesce((rule->>'maximum')::integer,100)
        and not exists(select 1 from jsonb_array_elements(value) item where not nexus_private.workflow_identifier(item))
        and (select count(*) from jsonb_array_elements(value))=(select count(distinct item) from jsonb_array_elements(value) item);
    when 'employee_snapshot' then
      if jsonb_typeof(value)<>'object' then return false; end if;
      select count(*) into field_count from jsonb_object_keys(value);
      return field_count=5 and value ?& array['id','name','branchId','active','rowVersion']
        and nexus_private.workflow_identifier(value->'id')
        and jsonb_typeof(value->'name')='string' and length(value->>'name')>0
        and (value->'branchId'='null'::jsonb or nexus_private.workflow_identifier(value->'branchId'))
        and jsonb_typeof(value->'active')='boolean' and jsonb_typeof(value->'rowVersion')='number'
        and value->>'rowVersion' ~ '^[1-9][0-9]*$'
        and (value->>'rowVersion')::numeric<=9007199254740991;
    else return false;
  end case;
exception when invalid_text_representation or numeric_value_out_of_range then
  return false;
end $$;
create or replace function nexus_private.workflow_legacy_read_only(body jsonb,definition jsonb) returns boolean
language plpgsql immutable set search_path='' as $$
declare field text; rule jsonb; value jsonb;
begin
  for field in select jsonb_array_elements_text(coalesce(definition->'requiredWriteFields','[]'::jsonb)) loop
    value:=body #> string_to_array(field,'.');
    if value is null or value='null'::jsonb then return true; end if;
  end loop;
  for rule in select item from jsonb_array_elements(coalesce(definition->'bodyGuards','[]'::jsonb)) rules(item) loop
    if not coalesce(nexus_private.workflow_body_guard(body #> string_to_array(rule->>'field','.'),rule,true),false) then return true; end if;
  end loop;
  return coalesce((definition->'legacyReadOnlyStates') ? nexus_private.workflow_state(body,definition),false);
end $$;

-- The existing guarded RPC uses this same projection function. legacyOnly is
-- historical SQL-only metadata and can never be supplied in a new public body.
create or replace function nexus_private.workflow_value(body jsonb,item jsonb) returns jsonb
language plpgsql immutable set search_path='' as $$
declare value jsonb;
begin
  if coalesce((item->>'legacyOnly')::boolean,false) then return 'null'::jsonb; end if;
  if item ? 'tagField' and body #>> string_to_array(item->>'tagField','.') is distinct from item->>'tagValue' then return 'null'::jsonb; end if;
  value:=body #> string_to_array(item->>'bodyField','.');
  return coalesce(value,'null'::jsonb);
end $$;

create or replace function nexus_private.workflow_guard() returns trigger
language plpgsql security definer set search_path='' as $$
declare d jsonb; b jsonb; old_b jsonb; row_json jsonb; typed jsonb:='{}'; c jsonb; f jsonb; child jsonb; v jsonb; discriminator jsonb; equality jsonb;
  field text; old_state text; new_state text; target_count integer:=0; protected boolean;
begin
  select definition into strict d from nexus_private.workflow_manifest where table_name=tg_table_name;
  if tg_op='DELETE' then
    if tg_table_name='mock_tickets' and (to_jsonb(old)->>'legacy_assignee_quarantined'='1'
      or to_jsonb(old)->>'assignee_id' is not null
      or (to_jsonb(old)->>'workflow_contract_version' is null and to_jsonb(old)->>'employee_assignee_id' is null)) then
      raise exception 'Legacy profile ticket is quarantined' using errcode='23514';
    end if;
    if tg_table_name='audit_events' or (tg_table_name='action_executions' and (to_jsonb(old)->'payload'->>'status') in ('verified_success','failed','denied')) then raise exception 'Immutable legacy history' using errcode='23514'; end if;
    if d->>'storage'<>'shared' and (d->>'storage'<>'mixed' or to_jsonb(old)->>'workflow_contract_version'='2') then raise exception 'Workflow history cannot be deleted' using errcode='23514'; end if;
    return old;
  end if;
  row_json:=to_jsonb(new); b:=row_json->(d->>'bodyColumn');
  if jsonb_typeof(b)<>'object' or jsonb_typeof(b->'id')<>'string' or b->>'id' is distinct from new.id then raise exception 'Invalid workflow body identity' using errcode='23514'; end if;
  protected:=d->>'storage'<>'mixed' or coalesce(row_json->>'workflow_contract_version'='2',false);
  if tg_table_name='mock_tickets' then
    if tg_op='INSERT' and (row_json->>'legacy_assignee_quarantined' is distinct from '0' or row_json->>'assignee_id' is not null) then
      raise exception 'Legacy profile assignee cannot be inserted' using errcode='23514';
    end if;
    if tg_op='UPDATE' then
      if row_json->'legacy_assignee_quarantined' is distinct from to_jsonb(old)->'legacy_assignee_quarantined' then
        raise exception 'Immutable ticket quarantine' using errcode='23514';
      end if;
      if to_jsonb(old)->>'legacy_assignee_quarantined'='1' or to_jsonb(old)->>'assignee_id' is not null
        or (to_jsonb(old)->>'workflow_contract_version' is null and to_jsonb(old)->>'employee_assignee_id' is null) then
        raise exception 'Legacy profile ticket is quarantined' using errcode='23514';
      end if;
      if row_json->>'assignee_id' is not null or b->>'assigneeId' is distinct from to_jsonb(old)->>'employee_assignee_id' then
        raise exception 'Immutable ticket employee assignee' using errcode='23514';
      end if;
    end if;
    if not exists(select 1 from public.employees e where e.id=b->>'assigneeId') then
      raise exception 'Ticket assignee must be an employee' using errcode='23514';
    end if;
  end if;
  if tg_op='UPDATE' then
    old_b:=to_jsonb(old)->(d->>'bodyColumn');
    if d->>'storage'='mixed' and row_json->'workflow_contract_version' is distinct from to_jsonb(old)->'workflow_contract_version' then raise exception 'Immutable workflow marker' using errcode='23514'; end if;
  end if;
  if not protected then
    if tg_op='UPDATE' and (tg_table_name='audit_events' or (tg_table_name='action_executions' and old_b->>'status' in ('verified_success','failed','denied'))) then raise exception 'Immutable legacy history' using errcode='23514'; end if;
    for discriminator in select value from jsonb_array_elements(d->'markerlessV2Discriminators') loop
      v:=b #> string_to_array(discriminator->>'path','.');
      if (coalesce((discriminator->>'presence')::boolean,false) and v is not null) or ((not discriminator ? 'equals') and v is not null and v<>'null'::jsonb) or (discriminator ? 'equals' and v=discriminator->'equals') then raise exception 'V2 row requires protected marker' using errcode='23514'; end if;
    end loop;
    if tg_table_name<>'mock_tickets' then return new; end if;
  end if;
  for equality in select value from jsonb_array_elements(d->'projectionEqualities') loop
    if (b #> string_to_array(equality->>'leftPath','.')) is distinct from (b #> string_to_array(equality->>'rightPath','.')) then raise exception 'Inconsistent workflow reference projection' using errcode='23514'; end if;
  end loop;
  if tg_table_name in ('pending_actions','action_executions') and b->>'contractVersion' is distinct from '2' then raise exception 'Protected workflow contract version required' using errcode='23514'; end if;
  if tg_table_name='pending_actions' and (b #>> '{policy,id}' is null or b #>> '{policy,version}' is null or b #>> '{policy,digest}' is null) then raise exception 'Missing workflow policy reference' using errcode='23514'; end if;
  if tg_op='INSERT' then
    if (d->>'storage'='shared' or (tg_table_name='mock_tickets' and not protected)) and new.row_version is null then new.row_version:=1; end if;
    if new.row_version is distinct from 1 then raise exception 'Invalid workflow insertion version' using errcode='23514'; end if;
  else
    if nexus_private.workflow_legacy_read_only(old_b,d) then raise exception 'Legacy workflow data is read-only' using errcode='23514'; end if;
    -- SQLite permits a first write to an existing, non-quarantined employee
    -- ticket whose V1 native version was NULL. Migration itself never fills it.
    if tg_table_name='mock_tickets' and not protected and old.row_version is null and new.row_version is null then new.row_version:=1; end if;
    if (d->>'storage'='shared' or (tg_table_name='mock_tickets' and not protected)) and new.row_version=old.row_version then new.row_version:=old.row_version+1; end if;
    if new.row_version is distinct from old.row_version+1
      and not (tg_table_name='mock_tickets' and not protected and old.row_version is null and new.row_version=1) then
      raise exception 'Invalid workflow conditional version' using errcode='23514';
    end if;
    for field in select jsonb_array_elements_text(d->'immutableFields') loop
      if b #> string_to_array(field,'.') is distinct from old_b #> string_to_array(field,'.') then raise exception 'Immutable workflow field' using errcode='23514'; end if;
    end loop;
    if exists(select 1 from jsonb_array_elements(d->'foreignKeys') x where x ? 'tagField') and b->'ref' is distinct from old_b->'ref' then raise exception 'Immutable workflow target reference' using errcode='23514'; end if;
    if coalesce((d->>'appendOnly')::boolean,false) and b is distinct from old_b then raise exception 'Append-only workflow history' using errcode='23514'; end if;
    if tg_table_name='pending_actions' and (b-'status'-'rowVersion') is distinct from (old_b-'status'-'rowVersion') then raise exception 'Immutable workflow approval' using errcode='23514'; end if;
    old_state:=nexus_private.workflow_state(old_b,d); new_state:=nexus_private.workflow_state(b,d);
    for field in select jsonb_array_elements_text(coalesce(d->'terminalImmutableFields'->old_state,'[]'::jsonb)) loop
      if b #> string_to_array(field,'.') is distinct from old_b #> string_to_array(field,'.') then raise exception 'Immutable terminal workflow field' using errcode='23514'; end if;
    end loop;
    if tg_table_name='action_executions' and old_state in ('verified_success','already_completed','failed','denied','stale') and b is distinct from old_b then raise exception 'Immutable historical receipt' using errcode='23514'; end if;
    if tg_table_name='action_targets' and old_state in ('verified','failed') and b is distinct from old_b then raise exception 'Immutable target proof' using errcode='23514'; end if;
    if old_state is distinct from new_state and d->'permittedTransitions'<>'{}'::jsonb and not coalesce((d->'permittedTransitions'->old_state) ? new_state,false) then
      if tg_table_name<>'incidents' or not exists(select 1 from public.action_executions r join public.pending_actions a on a.id=r.payload->>'actionId' join public.profiles p on p.id=a.payload->>'actorId' join public.sessions s on s.id=a.payload->>'sessionId' where r.workflow_contract_version is null and a.workflow_contract_version is null and b->>'operationKey'=r.id||':artifact' and r.payload->>'kind'='demo_update' and r.payload->>'status'='pending' and a.payload #>> '{payload,scenario}'='baseline' and a.payload->>'status'='claimed' and p.payload->>'active'='true' and s.profile_id=p.id and (p.payload->'permissions') ? 'demo.update') then raise exception 'Invalid workflow transition' using errcode='23514'; end if;
    end if;
  end if;
  if b ? 'rowVersion' and (jsonb_typeof(b->'rowVersion')<>'number' or b->>'rowVersion' !~ '^[0-9]+$' or (b->>'rowVersion')::bigint<>new.row_version) then raise exception 'Inconsistent workflow body version' using errcode='23514'; end if;
  if d->>'storage'<>'shared' and exists(select 1 from jsonb_object_keys(b) k where not (d->'bodyFields') ? k) then raise exception 'Unsupported workflow body field' using errcode='23514'; end if;
  for child in select value from jsonb_array_elements(d->'normalizedChildren') loop
    v:=b #> string_to_array(child->>'arrayBodyField','.');
    if coalesce((child->>'immutable')::boolean,false) and v is null then continue; end if;
    if jsonb_typeof(v) is distinct from 'array' then raise exception 'Invalid normalized workflow scope' using errcode='23514'; end if;
    if exists(select 1 from jsonb_array_elements(v) x where jsonb_typeof(x)<>'string') or (select count(*) from jsonb_array_elements(v))<>(select count(distinct value) from jsonb_array_elements(v)) then raise exception 'Invalid normalized workflow scope' using errcode='23514'; end if;
  end loop;
  for c in select value from jsonb_array_elements(d->'columns') loop
    if coalesce((c->>'legacyOnly')::boolean,false) then continue; end if;
    if coalesce((c->>'external')::boolean,false) then
      v:=row_json->(c->>'column');
      if tg_op='UPDATE' and v is distinct from to_jsonb(old)->(c->>'column') then raise exception 'Immutable workflow key projection' using errcode='23514'; end if;
    else v:=nexus_private.workflow_value(b,c); end if;
    if v='null'::jsonb then
      if not (c->>'nullable')::boolean then raise exception 'Missing workflow typed field' using errcode='23514'; end if;
    elsif (c->>'type'='text' and jsonb_typeof(v)<>'string') or (c->>'type'='boolean' and jsonb_typeof(v)<>'boolean')
      or (c->>'type' in ('integer','real') and jsonb_typeof(v)<>'number') then raise exception 'Invalid workflow typed field' using errcode='23514'; end if;
    if c->>'type'='integer' and v<>'null'::jsonb and (v::text !~ '^[0-9]+$') then raise exception 'Invalid workflow integral value' using errcode='23514'; end if;
    if c->>'type'='integer' and v<>'null'::jsonb and c->>'column' ~ '(version|attempt|quantity)$' and v::text='0' then raise exception 'Invalid workflow positive value' using errcode='23514'; end if;
    -- Explicit column tampering is rejected; omitted/stale legacy projections are derived.
    if row_json->(c->>'column') is not null and row_json->(c->>'column')<>'null'::jsonb
      and row_json->(c->>'column') is distinct from v
      and (tg_op='INSERT' or row_json->(c->>'column') is distinct from to_jsonb(old)->(c->>'column')) then raise exception 'Inconsistent workflow SQL projection' using errcode='23514'; end if;
    typed:=typed||jsonb_build_object(c->>'column',v);
  end loop;
  new:=jsonb_populate_record(new,typed);
  new_state:=nexus_private.workflow_state(b,d);
  if d->'permittedTransitions'<>'{}'::jsonb and (new_state is null or not (d->'permittedTransitions') ? new_state) then raise exception 'Invalid workflow status' using errcode='23514'; end if;
  for f in select value from jsonb_array_elements(d->'foreignKeys') where value ? 'tagField' loop
    if (to_jsonb(new)->(f->>'column'))<>'null'::jsonb then target_count:=target_count+1; end if;
  end loop;
  if exists(select 1 from jsonb_array_elements(d->'foreignKeys') x where x ? 'tagField') then
    if target_count<>1 or b->>'entityType' is distinct from b #>> '{ref,table}' then raise exception 'Invalid workflow target reference' using errcode='23514'; end if;
  end if;
  if tg_table_name='share_scope_branches' and not exists(select 1 from public.dashboard_shares s,jsonb_array_elements_text(s.payload->'approvedBranchIds') x where s.id=b->>'shareId' and s.workflow_contract_version=2 and x=b->>'branchId') then raise exception 'Invalid workflow relationship' using errcode='23514'; end if;
  if tg_table_name='onboarding_requests' then
    foreach field in array array['manager','director'] loop
      v:=b->(field||'ApprovalEventId');
      if (v is null or v='null'::jsonb) then
        if (field='manager' and b->>'state' in ('director_approval_pending','director_approved','onboarding_in_progress','completed')) or (field='director' and b->>'state' in ('director_approved','onboarding_in_progress','completed')) then raise exception 'Missing onboarding approval proof' using errcode='23514'; end if;
      elsif not exists(select 1 from public.onboarding_approval_events e where e.id=b->>(field||'ApprovalEventId') and e.request_id=new.id and e.stage=field and e.lifecycle_id=b->>'lifecycleId' and e.actor_identity_id=b->>(field||'IdentityId')) then raise exception 'Invalid onboarding approval proof' using errcode='23514'; end if;
    end loop;
  end if;
  if tg_table_name='action_idempotency_roots' and exists(select 1 from public.action_executions e where e.id=b->>'activeExecutionId' and e.workflow_contract_version=2 and e.root_id<>new.id) then raise exception 'Invalid workflow execution root' using errcode='23514'; end if;
  if tg_table_name='action_executions' and exists(select 1 from public.action_idempotency_roots r where r.active_execution_id=new.id and r.id<>(to_jsonb(new)->>'root_id')) then raise exception 'Invalid workflow execution root' using errcode='23514'; end if;
  if tg_table_name='policy_acknowledgement_tasks' and not exists(select 1 from public.policy_documents p where p.id=b->>'policyDocumentId' and p.version=b->>'policyVersion') then raise exception 'Invalid workflow policy reference' using errcode='23514'; end if;
  if tg_table_name='simulated_deliveries' and not exists(select 1 from public.dashboard_shares s where s.id=b->>'shareId' and s.workflow_contract_version=2 and s.recipient_identity_id=b->>'recipientIdentityId' and s.payload->>'channel'=b->>'channel' and s.execution_id=b->>'executionId') then raise exception 'Invalid workflow delivery reference' using errcode='23514'; end if;
  perform nexus_private.workflow_completeness_guard(tg_table_name,b,old_b,d,tg_op,new.row_version,case when tg_op='UPDATE' then old.row_version else null end);
  return new;
end $$;

create or replace function nexus_private.workflow_children() returns trigger
language plpgsql security definer set search_path='' as $$
declare d jsonb; child jsonb; b jsonb;
begin
  select definition into strict d from nexus_private.workflow_manifest where table_name=tg_table_name;
  b:=to_jsonb(new)->(d->>'bodyColumn');
  for child in select value from jsonb_array_elements(d->'normalizedChildren') loop
    if coalesce((child->>'immutable')::boolean,false) and tg_op='UPDATE' then continue; end if;
    execute format('delete from public.%I where %I=$1 and %I not in(select value from jsonb_array_elements_text($2))',child->>'table',child->>'parentIdColumn',child->>'childIdColumn') using new.id,b #> string_to_array(child->>'arrayBodyField','.');
    execute format('insert into public.%I(%I,%I) select $1,value from jsonb_array_elements_text($2) on conflict do nothing',child->>'table',child->>'parentIdColumn',child->>'childIdColumn') using new.id,b #> string_to_array(child->>'arrayBodyField','.');
  end loop;
  return null;
end $$;

create or replace function nexus_private.workflow_child_guard() returns trigger
language plpgsql security definer set search_path='' as $$
declare d jsonb; child jsonb; present boolean; row_data jsonb; parent_id text; target_id text; owned boolean;
begin
  select m.definition,x.value into strict d,child from nexus_private.workflow_manifest m cross join lateral jsonb_array_elements(m.definition->'normalizedChildren') x where x.value->>'table'=tg_table_name;
  row_data:=case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;
  parent_id:=row_data->>(child->>'parentIdColumn');target_id:=row_data->>(child->>'childIdColumn');
  execute format('select exists(select 1 from public.%I p,jsonb_array_elements_text(p.%I #> $3::text[]) x where p.id=$1 and x.value=$2)',d->>'table',d->>'bodyColumn') into present using parent_id,target_id,string_to_array(child->>'arrayBodyField','.');
  if child ? 'ownership' then
    if tg_op in('UPDATE','DELETE') then raise exception 'Immutable workflow assignment snapshot' using errcode='23514'; end if;
    execute format('select exists(select 1 from public.%I p join public.%I c on c.id=p.%I #>> $3::text[] join public.%I a on a.id=$2 where p.id=$1 and a.%I is not distinct from c.%I)',
      d->>'table',child #>> '{ownership,parentTable}',d->>'bodyColumn',child->>'target',
      lower(regexp_replace(child #>> '{ownership,targetOwnerField}','([A-Z])','_\1','g')),
      lower(regexp_replace(child #>> '{ownership,ownerField}','([A-Z])','_\1','g')))
      into owned using parent_id,target_id,string_to_array(child #>> '{ownership,parentReferenceField}','.');
    if not coalesce(owned,false) then raise exception 'Invalid workflow assignment ownership' using errcode='23514'; end if;
  end if;
  if (tg_op='DELETE' and present) or (tg_op<>'DELETE' and not present) then raise exception 'Scope projection must follow parent' using errcode='23514'; end if;
  if tg_op='UPDATE' and row_data is distinct from to_jsonb(old) then raise exception 'Scope projection must follow parent' using errcode='23514'; end if;
  if tg_op='DELETE' then return old; end if;return new;
end $$;

-- Relational proof twin of SQLite relationalChecks()/incidentProof. A matching
-- old event ID alone is insufficient: reviewed evidence and V2 execution matter.
create or replace function nexus_private.workflow_completeness_guard(
  table_name text,body jsonb,old_body jsonb,definition jsonb,
  operation text,version bigint,old_version bigint
) returns void language plpgsql security definer set search_path='' as $$
declare rule jsonb; field text; value jsonb;
begin
  for field in select jsonb_array_elements_text(coalesce(workflow_completeness_guard.definition->'requiredWriteFields','[]'::jsonb)) loop
    value:=workflow_completeness_guard.body #> string_to_array(field,'.');
    if value is null or value='null'::jsonb then raise exception 'Missing reviewed workflow metadata' using errcode='23514'; end if;
  end loop;
  for rule in select item from jsonb_array_elements(coalesce(workflow_completeness_guard.definition->'bodyGuards','[]'::jsonb)) rules(item) loop
    if not coalesce(nexus_private.workflow_body_guard(workflow_completeness_guard.body #> string_to_array(rule->>'field','.'),rule,false),false) then
      raise exception 'Invalid reviewed workflow metadata' using errcode='23514';
    end if;
  end loop;
  if workflow_completeness_guard.operation='INSERT' and workflow_completeness_guard.definition ? 'insertStates'
    and not (workflow_completeness_guard.definition->'insertStates') ? nexus_private.workflow_state(workflow_completeness_guard.body,workflow_completeness_guard.definition) then
    raise exception 'Invalid workflow creation state' using errcode='23514';
  end if;
  if workflow_completeness_guard.table_name='incidents' then
    if workflow_completeness_guard.operation='UPDATE' then
      if workflow_completeness_guard.body->>'escalationLifecycleId' is distinct from workflow_completeness_guard.old_body->>'escalationLifecycleId' then
        raise exception 'Immutable incident lifecycle' using errcode='23514';
      end if;
      if not ((workflow_completeness_guard.old_body->>'escalationStage' is null and workflow_completeness_guard.body->>'escalationStage' is null)
        or workflow_completeness_guard.body->>'escalationStage' is not distinct from workflow_completeness_guard.old_body->>'escalationStage'
        or (workflow_completeness_guard.old_body->>'escalationStage'='un_escalated' and workflow_completeness_guard.body->>'escalationStage'='team_requested'
          and workflow_completeness_guard.version=workflow_completeness_guard.old_version+1)) then
        raise exception 'Invalid incident escalation transition' using errcode='23514';
      end if;
      if workflow_completeness_guard.old_body->>'escalationStage'='team_requested' and workflow_completeness_guard.body->>'escalationEventId' is distinct from workflow_completeness_guard.old_body->>'escalationEventId' then
        raise exception 'Immutable incident terminal pointer' using errcode='23514';
      end if;
    end if;
    if not coalesce((workflow_completeness_guard.body->>'escalationStage' is null and workflow_completeness_guard.body->>'escalationLifecycleId' is null and workflow_completeness_guard.body->>'escalationEventId' is null)
      or (workflow_completeness_guard.body->>'escalationStage'='un_escalated' and nexus_private.workflow_identifier(workflow_completeness_guard.body->'escalationLifecycleId') and workflow_completeness_guard.body->>'escalationEventId' is null)
      or (workflow_completeness_guard.body->>'escalationStage'='team_requested' and exists(select 1 from public.incident_escalation_events e
        join public.workflow_teams t on t.id=e.team_id join public.action_executions x on x.id=e.execution_id
        where e.id=workflow_completeness_guard.body->>'escalationEventId' and e.incident_id=workflow_completeness_guard.body->>'id' and e.lifecycle_id=workflow_completeness_guard.body->>'escalationLifecycleId'
          and e.stage='team_requested' and t.id='demo_operations' and t.active
          and x.workflow_contract_version=2 and x.payload->>'kind'='incident_escalate'
          and e.body->>'reason' is not null and jsonb_typeof(e.body->'evidenceIds')='array'
          and nexus_private.workflow_body_guard(e.body->'reason','{"kind":"reason"}'::jsonb,false)
          and nexus_private.workflow_body_guard(e.body->'evidenceIds','{"kind":"id_array","minimum":1,"maximum":100}'::jsonb,false))),false) then
      raise exception 'Invalid incident escalation proof' using errcode='23514';
    end if;
  end if;
  if workflow_completeness_guard.table_name='incident_escalation_events' and not exists(select 1 from public.incidents i
    join public.workflow_teams t on t.id=workflow_completeness_guard.body->>'teamId' join public.action_executions x on x.id=workflow_completeness_guard.body->>'executionId'
    where i.id=workflow_completeness_guard.body->>'incidentId' and i.escalation_lifecycle_id=workflow_completeness_guard.body->>'lifecycleId'
      and i.escalation_stage in('un_escalated','team_requested') and workflow_completeness_guard.body->>'stage'='team_requested'
      and t.id='demo_operations' and t.active and x.workflow_contract_version=2 and x.payload->>'kind'='incident_escalate') then
    raise exception 'Invalid incident escalation event relationship' using errcode='23514';
  end if;
  if workflow_completeness_guard.table_name='offboarding_plans' then
    if not exists(select 1 from public.offboarding_cases c where c.id=workflow_completeness_guard.body->>'caseId'
      and c.employee_id=workflow_completeness_guard.body #>> '{employeeSnapshot,id}') then
      raise exception 'Invalid offboarding employee snapshot owner' using errcode='23514';
    end if;
    if workflow_completeness_guard.operation='INSERT' and not exists(select 1 from public.employees e where e.id=workflow_completeness_guard.body #>> '{employeeSnapshot,id}'
      and e.row_version=(workflow_completeness_guard.body #>> '{employeeSnapshot,rowVersion}')::bigint
      and e.name=workflow_completeness_guard.body #>> '{employeeSnapshot,name}'
      and e.branch_id is not distinct from workflow_completeness_guard.body #>> '{employeeSnapshot,branchId}'
      and e.active=(workflow_completeness_guard.body #>> '{employeeSnapshot,active}')::boolean) then
      raise exception 'Stale offboarding employee snapshot' using errcode='23514';
    end if;
  end if;
end $$;

do $finish$
declare item record; d jsonb; colname text; changed boolean;
begin
  -- Restore each original trigger mode exactly; no persistent migration bypass.
  for item in select * from pg_temp.workflow_completeness_trigger_modes loop
    execute format('alter table %s %s trigger %I',item.table_oid::regclass,
      case item.enabled when 'D' then 'disable' when 'R' then 'enable replica'
        when 'A' then 'enable always' else 'enable' end,item.trigger_name);
  end loop;
  if not exists(select 1 from pg_catalog.pg_trigger where tgrelid='public.offboarding_plans'::regclass and tgname='workflow_children') then
    create trigger workflow_children after insert or update on public.offboarding_plans
      for each row execute function nexus_private.workflow_children();
  end if;
  if not exists(select 1 from pg_catalog.pg_trigger where tgrelid='public.workflow_offboarding_plan_assignments'::regclass and tgname='workflow_child_guard') then
    create trigger workflow_child_guard before insert or update or delete on public.workflow_offboarding_plan_assignments
      for each row execute function nexus_private.workflow_child_guard();
    create trigger nexus_revision before insert or update or delete or truncate on public.workflow_offboarding_plan_assignments
      for each statement execute function nexus_private.workflow_revision();
  end if;
  -- Exact two-way relational comparison proves every original body/version/
  -- marker and row membership survives, including receipts and policy pins.
  for d in select definition from nexus_private.workflow_manifest order by table_name loop
    colname:=case when d->>'storage'='mixed' then 'workflow_contract_version' else 'null::integer' end;
    execute format('select exists((select id,%I::text,row_version,%s from public.%I except select id,body_text,row_version,contract_marker from pg_temp.workflow_completeness_rows where table_name=$1) union all (select id,body_text,row_version,contract_marker from pg_temp.workflow_completeness_rows where table_name=$1 except select id,%I::text,row_version,%s from public.%I))',
      d->>'bodyColumn',colname,d->>'table',d->>'bodyColumn',colname,d->>'table') into changed using d->>'table';
    if changed then raise exception 'Workflow completeness changed historical bodies or versions' using errcode='23514'; end if;
    execute format('select exists(select 1 from pg_temp.workflow_completeness_rows saved join public.%I current_row on current_row.id=saved.id cross join lateral jsonb_each(saved.original_columns) original_column where saved.table_name=$1 and to_jsonb(current_row)->original_column.key is distinct from original_column.value)',
      d->>'table') into changed using d->>'table';
    if changed then raise exception 'Workflow completeness changed an existing native projection' using errcode='23514'; end if;
  end loop;
  if (select revision from public.appmeta where singleton=1) is distinct from (select revision from pg_temp.workflow_completeness_state)
    or (select workflow_adapter_write from public.appmeta where singleton=1)<>0 then
    raise exception 'Workflow completeness changed application revision or adapter state' using errcode='23514';
  end if;
  if exists(select 1 from pg_temp.workflow_completeness_trigger_modes saved
    left join pg_catalog.pg_trigger actual on actual.tgrelid=saved.table_oid and actual.tgname=saved.trigger_name
    where actual.oid is null or actual.tgenabled is distinct from saved.enabled) then
    raise exception 'Workflow completeness failed to restore trigger guards' using errcode='23514';
  end if;
  insert into nexus_private.workflow_projection_migrations(id,definition_digest)
    select '202610030002_workflow_projection_completeness',digest from pg_temp.workflow_completeness_state
    on conflict(id) do nothing;
end $finish$;
-- Force deferred native FK validation before returning any migration success.
set constraints all immediate;
revoke all on function nexus_private.workflow_utf16_length(text),nexus_private.workflow_identifier(jsonb),
  nexus_private.workflow_business_date(jsonb),nexus_private.workflow_body_guard(jsonb,jsonb,boolean),
  nexus_private.workflow_legacy_read_only(jsonb,jsonb),
  nexus_private.workflow_completeness_guard(text,jsonb,jsonb,jsonb,text,bigint,bigint) from public,anon,authenticated,service_role;
commit;
